function validate([words1, words2]) {
  if (!Array.isArray(words1) || words1.length < 1 || words1.length > 1000) return 'words1 needs 1 to 1000 strings.';
  if (!Array.isArray(words2) || words2.length < 1 || words2.length > 1000) return 'words2 needs 1 to 1000 strings.';
  for (const w of [...words1, ...words2]) {
    if (typeof w !== 'string' || w.length < 1 || w.length > 30) return 'Each word has 1 to 30 letters.';
    if (!/^[a-z]+$/.test(w)) return 'Words use only lowercase English letters.';
  }
  return null;
}

