function countWords(words1, words2) {
  let total = 0;
  for (let i = 0; i < words1.length; i++) {
    const w = words1[i];
    let inFirst = 0;
    let inSecond = 0;
    for (const x of words1) if (x === w) inFirst++;
    for (const x of words2) if (x === w) inSecond++;
    if (inFirst === 1 && inSecond === 1) total++;
  }
  return total;
}

