function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (alphabet, maxLen) => {
    const len = 1 + Math.floor(rand() * maxLen);
    let s = '';
    for (let i = 0; i < len; i++) s += alphabet[Math.floor(rand() * alphabet.length)];
    return s;
  };
  if (size === 'large') {
    const pool = Array.from({ length: 1500 }, () => word(letters, 30));
    const pick = () => Array.from({ length: 1000 }, () => pool[Math.floor(rand() * pool.length)]);
    return [pick(), pick()];
  }
  const alphabet = letters.slice(0, 2 + Math.floor(rand() * 2));
  const maxLen = 1 + Math.floor(rand() * 2);
  const n1 = 1 + Math.floor(rand() * 7);
  const n2 = 1 + Math.floor(rand() * 7);
  return [Array.from({ length: n1 }, () => word(alphabet, maxLen)), Array.from({ length: n2 }, () => word(alphabet, maxLen))];
}
